import fs from 'node:fs';
const p='doing-market-public-2bl.js';
let s=fs.readFileSync(p,'utf8');
const from="function allSessions(){const st=getState(),tenantRows=Array.isArray(st?.sessions)?st.sessions.map(normalizeTenantSession):[];return globalSessions.length?globalSessions:tenantRows}";
const to="function allSessions(){const st=getState(),tenantRows=Array.isArray(st?.sessions)?st.sessions.map(normalizeTenantSession):[];return currentTenant()?tenantRows:(globalSessions.length?globalSessions:tenantRows)}";
const n=s.split(from).length-1;
if(n!==1)throw new Error('allSessions patch occurrence='+n);
s=s.replace(from,to);
fs.writeFileSync(p,s);
console.log('patched tenant-scoped session source');
